279	@Service
280	public class ClaimService {
281	
282	    private final ClaimRepository claims;
283	    private final PersonRepository people;
284	    private final RateRepository rates;
285	    private final StatementRepository statements;
286	    private final SheetService sheets;
287	    private final RollupService rollups;
288	    private final PeriodService periods;
289	    private final SettingsService settings;
290	    private final Audit audit;
291	
292	    public ClaimService(ClaimRepository claims, PersonRepository people, RateRepository rates,
293	            StatementRepository statements, SheetService sheets, RollupService rollups, PeriodService periods,
294	            SettingsService settings, Audit audit) {
295	        this.periods = periods;
296	        this.settings = settings;
297	        this.claims = claims;
298	        this.people = people;
299	        this.rates = rates;
300	        this.statements = statements;
301	        this.sheets = sheets;
302	        this.rollups = rollups;
303	        this.audit = audit;
304	    }
305	
306	    /** The sheet's claims, newest first. */
307	    @Transactional(readOnly = true)
308	    public List<Claim> list(String sheetId) {
309	        return claims.findBySheetIdOrderByIdDesc(sheetId);
310	    }
311	
312	    /**
313	     * Add a claim for a person; without a date it is dated the sheet's today. One dated in a closed
314	     * period is refused.
315	     */
316	    @Transactional
317	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
318	        sheets.lock(sheetId, user);
319	        Person person = people.findByIdAndSheetId(personId, sheetId)
320	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
321	        LocalDate dated = dateOrToday(sheetId, date);
322	        periods.requireOpenOn(sheetId, dated);
323	        requireNotRetired(person, dated);
324	        RollupService.Rollup before = rollups.snapshot(sheetId);
325	        Claim saved = claims.saveAndFlush(new Claim(sheetId, personId, amount, dated, noteOf(note)));
326	        audit(sheetId, user, "CLAIM_ADDED", person, saved, saved.getNumber());
327	        rollups.recordChanges(sheetId, user, before);
328	        return saved;
329	    }
330	
331	    /**
332	     * Change a draft claim's amount, date and note; without a date it is dated the sheet's today. A
333	     * claim that is no longer a draft is refused (an open one is voided and a new one added instead),
334	     * as is one dated in a closed period, or moved into one.
335	     */
336	    @Transactional
337	    public Claim edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note) {
338	        sheets.lock(sheetId, user);
339	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
340	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
341	        if (claim.getStatus() != ClaimStatus.DRAFT) {
342	            throw new ResponseStatusException(HttpStatus.CONFLICT,
343	                    "A " + claim.getStatus() + " claim cannot be edited");
344	        }
345	        LocalDate dated = dateOrToday(sheetId, date);
346	        periods.requireOpenOn(sheetId, claim.getDate());
347	        periods.requireOpenOn(sheetId, dated);
348	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
349	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
350	        requireNotRetired(owner, dated);
351	        RollupService.Rollup before = rollups.snapshot(sheetId);
352	        claim.setAmount(amount);
353	        claim.setDate(dated);
354	        claim.setNote(noteOf(note));
355	        Claim saved = claims.saveAndFlush(claim);
356	        Person person = people.findByIdAndSheetId(saved.getPersonId(), sheetId)
357	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
358	        audit(sheetId, user, "CLAIM_EDITED", person, saved, saved.getNumber());
359	        rollups.recordChanges(sheetId, user, before);
360	        return saved;
361	    }
362	
363	    /**
364	     * Move a claim to its next status; a change its current status does not allow is refused, as is
365	     * settling it by the user who opened it, settling it by a clerk when its due is above the sheet's
366	     * clerk limit (or it has none while there is a limit), and any change to a claim dated in a closed
367	     * period.
368	     */
369	    @Transactional
370	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next) {
371	        Sheet sheet = sheets.lock(sheetId, user);
372	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
373	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
374	        periods.requireOpenOn(sheetId, claim.getDate());
375	        if (!claim.getStatus().canBecome(next)) {
376	            throw new ResponseStatusException(HttpStatus.CONFLICT,
377	                    "A " + claim.getStatus() + " claim cannot become " + next);
378	        }
379	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
380	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it");
381	        }
382	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
383	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
384	        if (next == ClaimStatus.SETTLED) {
385	            requireMaySettle(sheet, user, person, claim);
386	        }
387	        RollupService.Rollup before = rollups.snapshot(sheetId);
388	        Integer number = next == ClaimStatus.OPEN ? Integer.valueOf(sheet.takeClaimNumber()) : claim.getNumber();
389	        claim.setStatus(next);
390	        claim.setNumber(number);
391	        if (next == ClaimStatus.OPEN) {
392	            claim.setOpenedBy(user);
393	        }
394	        if (next == ClaimStatus.SETTLED) {
395	            claim.setDue(figure(sheetId, person, claim));
396	        }
397	        Claim saved = claims.saveAndFlush(claim);
398	        String event = switch (next) {
399	            case OPEN -> "CLAIM_OPENED";
400	            case SETTLED -> "CLAIM_SETTLED";
401	            default -> "CLAIM_VOIDED";
402	        };
403	        String suffix = next == ClaimStatus.SETTLED
404	                ? " due=" + (saved.getDue() == null ? "n/a" : saved.getDue().setScale(2).toPlainString())
405	                : "";
406	        audit(sheetId, user, event, person, saved, number, suffix);
407	        rollups.recordChanges(sheetId, user, before);
408	        return saved;
409	    }
410	
411	    /**
412	     * Take a statement for a person on the sheet's today: their due-total then (the sum of the figures
413	     * of their claims that count, a held person's open ones not among them; n/a when their grade has
414	     * no rate in force today and none of those claims has a fixed or bound figure) is recorded, and each claim that counts is bound to its
415	     * figure then, the others left unbound. Their claims, newest first.
416	     */
417	    @Transactional
418	    public List<Claim> statement(String sheetId, String user, long personId) {
419	        Sheet sheet = sheets.lock(sheetId, user);
420	        Person person = people.findByIdAndSheetId(personId, sheetId)
421	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
422	        RollupService.Rollup before = rollups.snapshot(sheetId);
423	        List<Claim> theirs = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
424	                .filter(c -> c.getPersonId().equals(personId))
425	                .toList();
426	        List<Claim> counting = theirs.stream().filter(c -> RollupService.counts(person, c)).toList();
427	        boolean anyFixed = counting.stream().anyMatch(Claim::keepsFigure);
428	        boolean rated = rates.findInForce(sheetId, person.getGrade(), sheet.getToday()).isPresent();
429	        BigDecimal total = BigDecimal.ZERO.setScale(2);
430	        for (Claim c : theirs) {
431	            if (RollupService.counts(person, c)) {
432	                BigDecimal figure = figure(sheetId, person, c);
433	                if (figure != null) total = total.add(figure);
434	                c.bind(figure);
435	            } else {
436	                c.unbind();
437	            }
438	        }
439	        claims.saveAllAndFlush(theirs);
440	        BigDecimal dueTotal = rated || anyFixed ? total : null;
441	        statements.saveAndFlush(new Statement(sheetId, personId, sheet.getToday(), dueTotal, counting.size(), user));
442	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
443	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString())
444	                + " claims=" + counting.size());
445	        rollups.recordChanges(sheetId, user, before);
446	        return theirs;
447	    }
448	
449	    /** The figure a claim shows (see {@link RollupService#figure}); null when none. */
450	    private BigDecimal figure(String sheetId, Person person, Claim claim) {
451	        return rollups.figure(sheetId, person, claim);
452	    }
453	
454	    /**
455	     * Amounts are written as the screen shows them (two decimals), dates as yyyy-mm-dd; a claim
456	     * with a number (a voided one keeps it) ends with it.
457	     */
458	    private void audit(String sheetId, String user, String event, Person person, Claim claim, Integer number) {
459	        audit(sheetId, user, event, person, claim, number, "");
460	    }
461	
462	    /** As above, with {@code suffix} (fields a later change added) at the end of the line. */
463	    private void audit(String sheetId, String user, String event, Person person, Claim claim, Integer number,
464	            String suffix) {
465	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
466	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
467	                + (number != null ? " number=" + number : "") + suffix);
468	    }
469	
470	    /** Refuse a clerk settling a claim whose due is above the sheet's clerk limit; a steward settles any. */
471	    private void requireMaySettle(Sheet sheet, String user, Person person, Claim claim) {
472	        BigDecimal limit = sheet.getClerkLimit();
473	        if (limit == null || settings.roleOf(sheet.getId(), user) == Role.STEWARD) {
474	            return;
475	        }
476	        BigDecimal due = figure(sheet.getId(), person, claim);
477	        if (due == null || due.compareTo(limit) > 0) {
478	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
479	                    "A clerk cannot settle a claim whose due is above the clerk limit");
480	        }
481	    }
482	
483	    /** Refuse a claim dated after the person's retirement. */
484	    private static void requireNotRetired(Person person, LocalDate date) {
485	        if (person.retiredOn(date)) {
486	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That claim is dated after the person retired");
487	        }
488	    }
489	
490	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
491	        return date != null ? date : sheets.today(sheetId);
492	    }
493	
494	    private static String noteOf(String note) {
495	        return note == null ? "" : note.trim();
496	    }
497	}
