500	/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a DRAFT or OPEN claim can be VOID. */
501	public enum ClaimStatus {
502	    DRAFT, OPEN, SETTLED, VOID;
503	
504	    /** Whether a claim in this status counts toward claimed and due: open and settled ones do. */
505	    public boolean counts() {
506	        return this == OPEN || this == SETTLED;
507	    }
508	
509	    /** Whether a claim in this status may move to {@code next}. */
510	    public boolean canBecome(ClaimStatus next) {
511	        return switch (next) {
512	            case OPEN -> this == DRAFT;
513	            case SETTLED -> this == OPEN;
514	            case VOID -> this == DRAFT || this == OPEN;
515	            case DRAFT -> false;
516	        };
517	    }
518	}
