733	import net.officefloor.hq.app.sheet.SheetService;
734	import org.springframework.dao.DataIntegrityViolationException;
735	import org.springframework.http.HttpStatus;
736	import org.springframework.orm.ObjectOptimisticLockingFailureException;
737	import org.springframework.stereotype.Service;
738	import org.springframework.transaction.annotation.Transactional;
739	import org.springframework.web.server.ResponseStatusException;
740	
741	@Service
742	public class PersonService {
743	
744	    /** A person's statements: how many were taken, and the last one (null: none). */
745	    public record Statements(int count, Statement last) {
746	        public static final Statements NONE = new Statements(0, null);
747	    }
748	
749	    private final PersonRepository people;
750	    private final StatementRepository statements;
751	    private final SheetService sheets;
752	    private final RollupService rollups;
753	    private final Audit audit;
754	
755	    public PersonService(PersonRepository people, StatementRepository statements, SheetService sheets,
756	            RollupService rollups, Audit audit) {
757	        this.people = people;
758	        this.statements = statements;
759	        this.sheets = sheets;
760	        this.rollups = rollups;
761	        this.audit = audit;
762	    }
763	
764	    /** The sheet's people, in the order they were added. */
765	    @Transactional(readOnly = true)
766	    public List<Person> list(String sheetId) {
767	        return people.findBySheetIdOrderByIdAsc(sheetId);
768	    }
769	
770	    /** Each person's statements on the sheet, by person id; a person with none is absent. */
771	    @Transactional(readOnly = true)
772	    public Map<Long, Statements> statements(String sheetId) {
773	        Map<Long, Statements> out = new HashMap<>();
774	        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
775	            out.merge(s.getPersonId(), new Statements(1, s), (was, now) -> new Statements(was.count() + 1, s));
776	        }
777	        return out;
778	    }
779	
780	    /** Add a person (the sheet is started when it was never loaded before). */
781	    @Transactional
782	    public Person add(String sheetId, String user, String name, Grade grade) {
783	        sheets.load(sheetId, user);
784	        String trimmed = name.trim();
785	        requireUnusedName(sheetId, null, trimmed);
786	        RollupService.Rollup before = rollups.snapshot(sheetId);
787	        Person saved;
788	        try {
789	            saved = people.saveAndFlush(new Person(sheetId, trimmed, grade));
790	        } catch (DataIntegrityViolationException e) {
791	            throw nameInUse();
792	        }
793	        audit(sheetId, user, "PERSON_ADDED", saved);
794	        rollups.recordChanges(sheetId, user, before);
795	        return saved;
796	    }
797	
798	    /**
799	     * Change a person's name and grade, from the version of them the editor loaded: refused when
800	     * someone else has saved them since.
801	     */
802	    @Transactional
803	    public Person edit(String sheetId, String user, long personId, long version, String name, Grade grade) {
804	        Person person = people.findByIdAndSheetId(personId, sheetId)
805	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
806	        if (person.getVersion() != version) throw editedMeanwhile();
807	        String trimmed = name.trim();
808	        requireUnusedName(sheetId, personId, trimmed);
809	        RollupService.Rollup before = rollups.snapshot(sheetId);
810	        person.setName(trimmed);
811	        person.setGrade(grade);
812	        Person saved;
813	        try {
814	            saved = people.saveAndFlush(person);
815	        } catch (ObjectOptimisticLockingFailureException e) {
816	            throw editedMeanwhile();
817	        } catch (DataIntegrityViolationException e) {
818	            throw nameInUse();
819	        }
820	        audit(sheetId, user, "PERSON_EDITED", saved);
821	        rollups.recordChanges(sheetId, user, before);
822	        return saved;
823	    }
824	
825	    /** Retire a person from a date (the sheet's today when none is given). */
826	    @Transactional
827	    public Person retire(String sheetId, String user, long personId, LocalDate from) {
828	        sheets.lock(sheetId, user);
829	        Person person = people.findByIdAndSheetId(personId, sheetId)
830	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
831	        LocalDate dated = from != null ? from : sheets.today(sheetId);
832	        person.setRetiredFrom(dated);
833	        Person saved = people.saveAndFlush(person);
834	        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user
835	                + " name=" + saved.getName() + " from=" + dated);
836	        return saved;
837	    }
838	
839	    /**
840	     * Put a person on hold, or release them when held. Followed by the rollup lines of the figures it
841	     * moves (their open claims leave, or rejoin, the live totals).
842	     */
843	    @Transactional
844	    public Person toggleHold(String sheetId, String user, long personId) {
845	        sheets.lock(sheetId, user);
846	        Person person = people.findByIdAndSheetId(personId, sheetId)
847	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
848	        RollupService.Rollup before = rollups.snapshot(sheetId);
849	        person.setHeld(!person.isHeld());
850	        Person saved = people.saveAndFlush(person);
851	        audit.recordOnCommit((saved.isHeld() ? "PERSON_HELD" : "PERSON_RELEASED") + " sheet=" + sheetId
852	                + " by=" + user + " name=" + saved.getName());
853	        rollups.recordChanges(sheetId, user, before);
854	        return saved;
855	    }
856	
857	    private void audit(String sheetId, String user, String event, Person person) {
858	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user
859	                + " name=" + person.getName() + " grade=" + person.getGrade());
860	    }
861	
862	    /** Refuse a name another person on the sheet already has, ignoring case. */
863	    private void requireUnusedName(String sheetId, Long personId, String name) {
864	        String key = name.toLowerCase(Locale.ROOT);
865	        boolean used = people.findBySheetIdOrderByIdAsc(sheetId).stream()
866	                .anyMatch(p -> !p.getId().equals(personId) && p.getName().toLowerCase(Locale.ROOT).equals(key));
867	        if (used) throw nameInUse();
868	    }
869	
870	    private static ResponseStatusException editedMeanwhile() {
871	        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED, "Someone else has saved this person since");
872	    }
873	
874	    private static ResponseStatusException nameInUse() {
875	        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use");
876	    }
877	}
